import React from "react";
import "./adpage.css";

const AdPage = () => {
  const products = [
    { id: 1, name: "Smartphone", brand: "Samsung", image: "https://via.placeholder.com/150" },
    { id: 2, name: "Shoes", brand: "Nike", image: "https://via.placeholder.com/150" },
    { id: 3, name: "Headphones", brand: "Sony", image: "https://via.placeholder.com/150" },
    { id: 4, name: "Laptop", brand: "Dell", image: "https://via.placeholder.com/150" }
  ];

  return (
    <div className="ad-page-container">
      {/* Top Advertisement Box */}
      <div className="ad-banner">
        <img
          src="https://via.placeholder.com/1200x300?text=Big+Ad+Banner"
          alt="Advertisement"
          className="ad-image"
        />
      </div>

      {/* Product/Brand Cards */}
      <div className="cards-section">
        {products.map((product) => (
          <div key={product.id} className="product-card">
            <img src={product.image} alt={product.name} className="product-image" />
            <div className="product-info">
              <h3>{product.name}</h3>
              <p>{product.brand}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AdPage;
